Design:
- Cache-aside with a TTL.
- In-flight request dedupe, so concurrent misses trigger one fetch.
- LRU size cap.
- Explicit invalidation on writes.
- A `CacheStore` interface, so you can swap in Redis later.

```ts
// cache.ts
export interface CacheStore<V> {
  get(key: string): Promise<V | undefined>;
  set(key: string, value: V, ttlMs: number): Promise<void>;
  delete(key: string): Promise<void>;
}

export class MemoryStore<V> implements CacheStore<V> {
  private map = new Map<string, { value: V; expires: number }>();
  constructor(private maxEntries = 10_000) {}

  async get(key: string) {
    const hit = this.map.get(key);
    if (!hit) return undefined;
    if (hit.expires <= Date.now()) {
      this.map.delete(key);
      return undefined;
    }
    // refresh LRU position
    this.map.delete(key);
    this.map.set(key, hit);
    return hit.value;
  }

  async set(key: string, value: V, ttlMs: number) {
    this.map.delete(key);
    this.map.set(key, { value, expires: Date.now() + ttlMs });
    if (this.map.size > this.maxEntries) {
      const oldest = this.map.keys().next().value!;
      this.map.delete(oldest);
    }
  }

  async delete(key: string) {
    this.map.delete(key);
  }
}

export class CachedLoader<V> {
  private inflight = new Map<string, Promise<V>>();

  constructor(
    private store: CacheStore<V>,
    private load: (key: string) => Promise<V>,
    private ttlMs = 60_000,
  ) {}

  async get(key: string): Promise<V> {
    const cached = await this.store.get(key);
    if (cached !== undefined) return cached;

    const pending = this.inflight.get(key);
    if (pending) return pending;

    const p = this.load(key)
      .then(async (value) => {
        await this.store.set(key, value, this.ttlMs);
        return value;
      })
      .finally(() => this.inflight.delete(key));
    this.inflight.set(key, p);
    return p;
  }

  invalidate(key: string) {
    this.inflight.delete(key);
    return this.store.delete(key);
  }
}
```

