```ts
// profileCache.ts
import Redis from "ioredis";

const redis = new Redis(process.env.REDIS_URL!);

const TTL_SECONDS = 300;      // fresh window
const NEG_TTL_SECONDS = 30;   // cache "not found" briefly
const key = (id: string) => `profile:v1:${id}`; // bump v1 on schema change

const inflight = new Map<string, Promise<Profile | null>>(); // per-process stampede guard

export async function getProfile(
  id: string,
  load: (id: string) => Promise<Profile | null>, // DB / upstream fetch
): Promise<Profile | null> {
  try {
    const hit = await redis.get(key(id));
    if (hit !== null) return JSON.parse(hit); // "null" = cached miss
  } catch {
    // Redis down: fall through to source. Cache never breaks API.
  }

  const pending = inflight.get(id);
  if (pending) return pending;

  const p = (async () => {
    const profile = await load(id);
    try {
      await redis.set(
        key(id),
        JSON.stringify(profile),
        "EX",
        // jitter ±10% avoids synchronized expiry
        Math.round((profile ? TTL_SECONDS : NEG_TTL_SECONDS) * (0.9 + Math.random() * 0.2)),
      );
    } catch {}
    return profile;
  })().finally(() => inflight.delete(id));

  inflight.set(id, p);
  return p;
}

export async function invalidateProfile(id: string) {
  try { await redis.del(key(id)); } catch {}
}
```

