// cache/redisStore.ts  (ioredis)
import type Redis from "ioredis";
import type { CacheStore } from "./store";

export class RedisStore<V> implements CacheStore<V> {
  constructor(private redis: Redis, private prefix = "cache:") {}

  async get(key: string) {
    const raw = await this.redis.get(this.prefix + key);
    return raw === null ? undefined : (JSON.parse(raw) as V);
  }
  async set(key: string, value: V, ttlMs: number) {
    await this.redis.set(this.prefix + key, JSON.stringify(value), "PX", ttlMs);
  }
  async del(key: string) {
    await this.redis.del(this.prefix + key);
  }
}
