```ts
// cache/profileCache.ts
import type { CacheStore } from "./store";

export interface Profile {
  id: string;
  name: string;
  email: string;
  // ...
}

// null = confirmed not found (negative cache)
type Entry = Profile | null;

const TTL_MS = 5 * 60_000;
const NEGATIVE_TTL_MS = 30_000;

export class ProfileCache {
  private inflight = new Map<string, Promise<Entry>>();

  constructor(
    private store: CacheStore<Entry>,
    private loader: (id: string) => Promise<Profile | null>,
  ) {}

  private key(id: string) {
    return `profile:v1:${id}`; // bump v1 on schema change
  }

  async get(id: string): Promise<Profile | null> {
    const key = this.key(id);

    try {
      const cached = await this.store.get(key);
      if (cached !== undefined) return cached;
    } catch {
      // cache down: fall through to source, do not fail request
    }

    // single-flight: concurrent misses share one DB call
    let pending = this.inflight.get(key);
    if (!pending) {
      pending = this.load(id, key).finally(() => this.inflight.delete(key));
      this.inflight.set(key, pending);
    }
    return pending;
  }

  private async load(id: string, key: string): Promise<Entry> {
    const fresh = await this.loader(id);
    const ttl = fresh ? jitter(TTL_MS) : NEGATIVE_TTL_MS;
    try {
      await this.store.set(key, fresh, ttl);
    } catch {
      /* ignore cache write failure */
    }
    return fresh;
  }

  async invalidate(id: string): Promise<void> {
    const key = this.key(id);
    this.inflight.delete(key);
    await this.store.del(key);
  }
}

// +-10% so keys written together do not expire together
function jitter(ms: number) {
  return Math.round(ms * (0.9 + Math.random() * 0.2));
}
```

