export interface CacheStore<V> {
  get(key: string): Promise<V | undefined>;
  set(key: string, value: V, ttlMs: number): Promise<void>;
  del(key: string): Promise<void>;
}

// In-memory LRU + TTL store (single-process only)
export class MemoryStore<V> implements CacheStore<V> {
  private map = new Map<string, { value: V; expires: number }>();
  constructor(private maxEntries = 10_000) {}

  async get(key: string) {
    const hit = this.map.get(key);
    if (!hit) return undefined;
    if (hit.expires <= Date.now()) {
      this.map.delete(key);
      return undefined;
    }
    // refresh recency (Map preserves insertion order)
    this.map.delete(key);
    this.map.set(key, hit);
    return hit.value;
  }

  async set(key: string, value: V, ttlMs: number) {
    this.map.delete(key);
    this.map.set(key, { value, expires: Date.now() + ttlMs });
    if (this.map.size > this.maxEntries) {
      const oldest = this.map.keys().next().value!;
      this.map.delete(oldest);
    }
  }

  async del(key: string) {
    this.map.delete(key);
  }
}

