// npm i express express-session argon2 helmet
const express = require("express");
const session = require("express-session");
const argon2 = require("argon2");
const helmet = require("helmet");

const app = express();
app.use(helmet());
app.use(express.json({ limit: "10kb" }));
app.set("trust proxy", 1); // only if behind one proxy; needed for correct req.ip

app.use(
  session({
    name: "sid",
    secret: process.env.SESSION_SECRET, // long random, required
    resave: false,
    saveUninitialized: false,
    // MemoryStore = dev only. Use connect-redis in prod.
    cookie: {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      maxAge: 1000 * 60 * 60, // 1h
    },
  })
);

// ---- user store (replace with DB) ----
const users = new Map(); // username -> { id, username, hash }

// ---- failed-attempt limiter ----
const MAX_FAILS = 5;
const WINDOW_MS = 15 * 60 * 1000;
const LOCK_MS = 15 * 60 * 1000;
const attempts = new Map(); // key -> { count, first, lockedUntil }

function check(key) {
  const now = Date.now();
  const rec = attempts.get(key);
  if (!rec) return 0;
  if (rec.lockedUntil > now) return rec.lockedUntil - now;
  if (now - rec.first > WINDOW_MS) attempts.delete(key);
  return 0;
}

function fail(key) {
  const now = Date.now();
  let rec = attempts.get(key);
  if (!rec || now - rec.first > WINDOW_MS) {
    rec = { count: 0, first: now, lockedUntil: 0 };
  }
  rec.count++;
  if (rec.count >= MAX_FAILS) rec.lockedUntil = now + LOCK_MS;
  attempts.set(key, rec);
}

setInterval(() => {
  const now = Date.now();
  for (const [k, r] of attempts)
    if (r.lockedUntil < now && now - r.first > WINDOW_MS) attempts.delete(k);
}, 60_000).unref();

// ---- argon2 config ----
const ARGON = { type: argon2.argon2id, memoryCost: 19456, timeCost: 2, parallelism: 1 };
// Dummy hash: verify runs even for unknown user, so timing does not leak existence.
const DUMMY_HASH_PROMISE = argon2.hash("dummy-password", ARGON);

// ---- routes ----
app.post("/register", async (req, res) => {
  const { username, password } = req.body ?? {};
  if (typeof username !== "string" || typeof password !== "string")
    return res.status(400).json({ error: "Invalid input" });
  if (username.length < 3 || username.length > 64 || password.length < 12 || password.length > 128)
    return res.status(400).json({ error: "Username 3-64 chars, password 12-128 chars" });
  const name = username.toLowerCase();
  if (users.has(name)) return res.status(409).json({ error: "Username taken" });
  users.set(name, {
    id: users.size + 1,
    username: name,
    hash: await argon2.hash(password, ARGON),
  });
  res.status(201).json({ ok: true });
});

app.post("/login", async (req, res) => {
  const { username, password } = req.body ?? {};
  if (typeof username !== "string" || typeof password !== "string")
    return res.status(400).json({ error: "Invalid input" });

  const name = username.toLowerCase();
  const ipKey = `ip:${req.ip}`;
  const userKey = `user:${name}`; // stops distributed guessing on one account

  const wait = Math.max(check(ipKey), check(userKey));
  if (wait > 0) {
    res.set("Retry-After", Math.ceil(wait / 1000));
    return res.status(429).json({ error: "Too many attempts. Try later." });
  }

  const user = users.get(name);
  const hash = user ? user.hash : await DUMMY_HASH_PROMISE;
  let ok = false;
  try {
    ok = await argon2.verify(hash, password);
  } catch {}
  ok = ok && !!user;

  if (!ok) {
    fail(ipKey);
    fail(userKey);
    return res.status(401).json({ error: "Invalid credentials" }); // generic
  }

  attempts.delete(ipKey);
  attempts.delete(userKey);

  // Rehash if params upgraded
  if (argon2.needsRehash(user.hash, ARGON)) user.hash = await argon2.hash(password, ARGON);

  // Regenerate ID: blocks session fixation
  req.session.regenerate((err) => {
    if (err) return res.status(500).json({ error: "Server error" });
    req.session.userId = user.id;
    req.session.save((err2) => {
      if (err2) return res.status(500).json({ error: "Server error" });
      res.json({ ok: true });
    });
  });
});

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: "Unauthorized" });
  next();
}

app.get("/me", requireAuth, (req, res) => res.json({ userId: req.session.userId }));

app.post("/logout", (req, res) => {
  req.session.destroy(() => {
    res.clearCookie("sid");
    res.json({ ok: true });
  });
});

app.listen(3000);
```

Design notes:

- **Hashing:** argon2id, per-password salt built in. `needsRehash` upgrades old hashes on login.
- **Rate limit:** two keys, IP and username. IP key stops one attacker spraying many accounts. Username key stops many IPs hitting one account. 5 fails → 15 min lock, `429` with `Retry-After`. Success clears counters.
- **Username-key DoS:** attacker can lock a victim out on purpose. Tradeoff accepted here. Mitigate with CAPTCHA or progressive delay.
- **Timing:** dummy hash verify for unknown users. Same generic `401` message for both failure cases.
- **Sessions:** `regenerate` on login stops fixation. Cookie is `httpOnly`, `secure` in prod, `sameSite: lax`.
- **Production changes:**
  - Swap `MemoryStore` and the `attempts` Map for Redis (`connect-redis`, or `rate-limiter-flexible`). In-memory state breaks across multiple processes and resets on restart.
  - Add CSRF protection if you use cookie auth with state-changing routes. `sameSite` helps but is not enough alone.
  - Serve over HTTPS only.
  - Add a per-IP limiter on `/register`.
  - Never log passwords.

