// app.js
const express = require('express');
const session = require('express-session');
const bcrypt = require('bcrypt');

const app = express();
app.use(express.json({ limit: '10kb' }));
// app.set('trust proxy', 1); // enable if behind proxy, else req.ip is proxy IP

// ---- Sessions ----
if (!process.env.SESSION_SECRET) throw new Error('SESSION_SECRET required');
app.use(session({
  name: 'sid',
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,           // no session until login
  // store: new RedisStore({ client }), // default MemoryStore is dev only
  cookie: {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    maxAge: 1000 * 60 * 60 * 2,       // 2h
  },
}));

// ---- User store (replace with DB) ----
const users = new Map(); // username -> { id, passwordHash }
const BCRYPT_ROUNDS = 12;
// Compare against this when user not found: equal timing, no user enumeration.
const DUMMY_HASH = bcrypt.hashSync('dummy-password', BCRYPT_ROUNDS);

// ---- Failed-attempt limiter (in-memory; use Redis for multi-instance) ----
const WINDOW_MS = 15 * 60 * 1000;
const LOCK_MS = 15 * 60 * 1000;
const MAX_PER_ACCOUNT_IP = 5;   // per (username, ip)
const MAX_PER_IP = 20;          // per ip, any username
const attempts = new Map();     // key -> { count, windowStart, lockedUntil }

function getEntry(key, now) {
  let e = attempts.get(key);
  if (!e || (now - e.windowStart > WINDOW_MS && e.lockedUntil <= now)) {
    e = { count: 0, windowStart: now, lockedUntil: 0 };
    attempts.set(key, e);
  }
  return e;
}

function lockedFor(keys) {
  const now = Date.now();
  let wait = 0;
  for (const k of keys) {
    const e = attempts.get(k);
    if (e && e.lockedUntil > now) wait = Math.max(wait, e.lockedUntil - now);
  }
  return wait;
}

function recordFailure(keys, limits) {
  const now = Date.now();
  keys.forEach((k, i) => {
    const e = getEntry(k, now);
    e.count += 1;
    if (e.count >= limits[i]) e.lockedUntil = now + LOCK_MS;
  });
}

setInterval(() => {
  const now = Date.now();
  for (const [k, e] of attempts) {
    if (e.lockedUntil <= now && now - e.windowStart > WINDOW_MS) attempts.delete(k);
  }
}, 60 * 1000).unref();

// ---- Helpers ----
const validCreds = (u, p) =>
  typeof u === 'string' && typeof p === 'string' &&
  u.length >= 3 && u.length <= 64 &&
  p.length >= 8 && p.length <= 72; // bcrypt truncates past 72 bytes

const requireAuth = (req, res, next) =>
  req.session.userId ? next() : res.status(401).json({ error: 'Unauthorized' });

// ---- Routes ----
app.post('/register', async (req, res) => {
  const { username, password } = req.body || {};
  if (!validCreds(username, password)) return res.status(400).json({ error: 'Invalid input' });
  const name = username.toLowerCase();
  if (users.has(name)) return res.status(409).json({ error: 'Username taken' });
  const passwordHash = await bcrypt.hash(password, BCRYPT_ROUNDS);
  users.set(name, { id: users.size + 1, passwordHash });
  res.status(201).json({ ok: true });
});

app.post('/login', async (req, res) => {
  const { username, password } = req.body || {};
  if (!validCreds(username, password)) return res.status(400).json({ error: 'Invalid credentials' });

  const name = username.toLowerCase();
  const keys = [`acct:${name}|${req.ip}`, `ip:${req.ip}`];
  const limits = [MAX_PER_ACCOUNT_IP, MAX_PER_IP];

  const wait = lockedFor(keys);
  if (wait > 0) {
    res.set('Retry-After', String(Math.ceil(wait / 1000)));
    return res.status(429).json({ error: 'Too many failed attempts. Try later.' });
  }

  const user = users.get(name);
  const ok = await bcrypt.compare(password, user ? user.passwordHash : DUMMY_HASH);

  if (!user || !ok) {
    recordFailure(keys, limits);
    return res.status(401).json({ error: 'Invalid credentials' }); // same msg both cases
  }

