```js
// server.js
const express = require('express');
const session = require('express-session');
const bcrypt = require('bcrypt');
const rateLimit = require('express-rate-limit');

const app = express();
const isProd = process.env.NODE_ENV === 'production';
const COST = 12;
const MAX_FAILS = 5;
const LOCK_MS = 15 * 60 * 1000;

if (isProd) app.set('trust proxy', 1); // behind proxy: needed for secure cookie + real IP

app.use(express.json({ limit: '10kb' }));
app.use(session({
  name: 'sid',
  secret: process.env.SESSION_SECRET,   // long random string, required
  resave: false,
  saveUninitialized: false,             // no session until login
  // store: new RedisStore({ client }), // MemoryStore leaks, single process only
  cookie: {
    httpOnly: true,
    secure: isProd,
    sameSite: 'lax',
    maxAge: 60 * 60 * 1000,
  },
}));

// --- demo user store: swap for DB ---
const users = new Map(); // username -> { id, hash }
const DUMMY_HASH = bcrypt.hashSync('dummy-password', COST); // equalize timing for unknown users

// --- rate limit layer 1: per IP ---
const ipLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 20,
  skipSuccessfulRequests: true, // count only failures (status < 400)
  standardHeaders: 'draft-7',
  legacyHeaders: false,
  message: { error: 'Too many attempts. Try later.' },
});

// --- rate limit layer 2: per account lockout ---
const fails = new Map(); // username -> { count, lockUntil }

function lockRemainingMs(name) {
  const f = fails.get(name);
  if (!f || !f.lockUntil) return 0;
  const left = f.lockUntil - Date.now();
  if (left <= 0) { fails.delete(name); return 0; }
  return left;
}
function recordFail(name) {
  const f = fails.get(name) || { count: 0, lockUntil: 0 };
  f.count += 1;
  if (f.count >= MAX_FAILS) f.lockUntil = Date.now() + LOCK_MS;
  fails.set(name, f);
}

// periodic cleanup of stale entries
setInterval(() => {
  for (const [k, f] of fails) if (f.lockUntil && f.lockUntil < Date.now()) fails.delete(k);
}, 10 * 60 * 1000).unref();

const validCreds = (u, p) =>
  typeof u === 'string' && typeof p === 'string' &&
  u.length >= 3 && u.length <= 64 &&
  p.length >= 8 && Buffer.byteLength(p) <= 72; // bcrypt truncates past 72 bytes

app.post('/register', async (req, res) => {
  const { username, password } = req.body ?? {};
  if (!validCreds(username, password)) return res.status(400).json({ error: 'Invalid input' });
  const name = username.toLowerCase();
  if (users.has(name)) return res.status(409).json({ error: 'Username taken' });
  users.set(name, { id: users.size + 1, hash: await bcrypt.hash(password, COST) });
  res.status(201).json({ ok: true });
});

app.post('/login', ipLimiter, async (req, res, next) => {
  try {
    const { username, password } = req.body ?? {};
    if (!validCreds(username, password)) return res.status(400).json({ error: 'Invalid input' });
    const name = username.toLowerCase();

    const left = lockRemainingMs(name);
    if (left > 0) {
      res.set('Retry-After', String(Math.ceil(left / 1000)));
      return res.status(429).json({ error: 'Account temporarily locked' });
    }

    const user = users.get(name);
    const match = await bcrypt.compare(password, user ? user.hash : DUMMY_HASH);
    if (!user || !match) {
      recordFail(name);
      return res.status(401).json({ error: 'Invalid credentials' }); // same msg both cases
    }

    fails.delete(name);
    // new session ID on privilege change: blocks session fixation
    req.session.regenerate((err) => {
      if (err) return next(err);
      req.session.userId = user.id;
      req.session.save((err2) => (err2 ? next(err2) : res.json({ ok: true })));
    });
  } catch (e) { next(e); }
});

const requireAuth = (req, res, next) =>
  req.session.userId ? next() : res.status(401).json({ error: 'Login required' });

app.get('/me', requireAuth, (req, res) => res.json({ userId: req.session.userId }));

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('sid');
    res.json({ ok: true });
  });
});

app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: 'Server error' });
});

app.listen(3000);
```

Key points:
- **Hashing:** bcrypt cost 12. Dummy hash compare for unknown users stops timing-based username enumeration.
- **Session:** `regenerate` on login stops session fixation. Cookie is `httpOnly`, `secure` in prod, `sameSite=lax`. `saveUninitialized: false` avoids anonymous sessions.
- **Rate limit:** two layers.
  - Per IP: `skipSuccessfulRequests` counts only failures.
  - Per account: 5 fails triggers a 15 minute lock.
- **Lockout tradeoff:** an attacker can lock a known victim's account on purpose. Mitigate with a per-username+IP key, a CAPTCHA, or exponential backoff instead of a hard lock.
- **Prod gaps:**
  - Move `users` to a DB.
  - Use a Redis store for sessions.
  - Use `rate-limit-redis` and a Redis-backed `fails` map, so limits survive restarts and work across instances.
  - Add CSRF protection if you use cookies with cross-site forms. `sameSite` helps but is not enough alone.
  - Serve over HTTPS.

