const DUMMY = bcrypt.hashSync('dummy', 12); // equalizes timing for unknown users
const MAX_FAILS = 5, LOCK_MS = 15 * 60 * 1000;

// per-IP: only failed requests count
const ipLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 10,
  skipSuccessfulRequests: true,
  standardHeaders: true,
  legacyHeaders: false,
});

const valid = (u, p) =>
  typeof u === 'string' && typeof p === 'string' &&
  u.length >= 3 && u.length <= 64 &&
  p.length >= 8 && Buffer.byteLength(p) <= 72; // bcrypt truncates at 72 bytes

app.post('/register', ipLimiter, async (req, res) => {
  const { username, password } = req.body ?? {};
  if (!valid(username, password)) return res.sendStatus(400);
  const key = username.toLowerCase();
  if (users.has(key)) return res.sendStatus(409);
  users.set(key, { hash: await bcrypt.hash(password, 12) });
  res.sendStatus(201);
});

app.post('/login', ipLimiter, async (req, res) => {
  const { username, password } = req.body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string' ||
      Buffer.byteLength(password) > 72) return res.sendStatus(400);

  const key = username.toLowerCase();
  const f = fails.get(key);
  if (f && f.until > Date.now()) {
    return res.status(429).json({ error: 'Too many attempts, try later' });
  }

  const user = users.get(key);
  const match = await bcrypt.compare(password, user ? user.hash : DUMMY);

  if (!user || !match) {
    const count = (f?.count ?? 0) + 1;
    fails.set(key, count >= MAX_FAILS
      ? { count: 0, until: Date.now() + LOCK_MS }
      : { count, until: 0 });
    return res.status(401).json({ error: 'Invalid credentials' }); // same msg either way
  }

  fails.delete(key);
  req.session.regenerate(err => {           // new sid → blocks session fixation
    if (err) return res.sendStatus(500);
    req.session.user = key;
    res.json({ ok: true });
  });
});

const requireAuth = (req, res, next) =>
  req.session.user ? next() : res.sendStatus(401);

app.get('/me', requireAuth, (req, res) => res.json({ user: req.session.user }));

app.post('/logout', (req, res) => {
  req.session.destroy(() => {
    res.clearCookie('sid');
    res.sendStatus(204);
  });
});

app.listen(3000);
```

**Design choices**
- **Two limiters:** Per-IP (`express-rate-limit`) slows one attacker. Per-account lockout stops distributed guessing. Unknown usernames are tracked too, so the responses don't reveal which accounts exist.
- **Lockout can be abused:** Anyone can lock out a known username for 15 minutes. If that matters, key on username+IP or add exponential backoff.
- **State is in memory:** `fails` and the limiter's counters reset on restart and aren't shared across instances. Use Redis (`rate-limit-redis`) when you run more than one process. Cap or expire `fails` entries too.
- **Not included:** CSRF tokens. `sameSite: 'lax'` covers most cases, but add `csrf-csrf` if you need more. Also missing are password-strength checks, email verification and password reset.

