import express from "express";
import session from "express-session";
import argon2 from "argon2";

const isProd = process.env.NODE_ENV === "production";
const SESSION_SECRET = process.env.SESSION_SECRET;
if (!SESSION_SECRET) throw new Error("SESSION_SECRET is required");

const app = express();
if (isProd) app.set("trust proxy", 1); // so req.ip is the real client IP behind a proxy
app.use(express.json({ limit: "10kb" }));

// ---------- Sessions ----------
app.use(
  session({
    name: "sid",
    secret: SESSION_SECRET,
    resave: false,
    saveUninitialized: false, // no session (or cookie) until login
    // MemoryStore is for dev only. Use connect-redis or similar in production.
    cookie: {
      httpOnly: true,            // not readable from JS
      secure: isProd,            // HTTPS only in prod
      sameSite: "lax",           // basic CSRF mitigation
      maxAge: 1000 * 60 * 60 * 8 // 8 hours
    },
  })
);

// ---------- User store (replace with a real DB) ----------
const users = new Map(); // username -> { id, username, passwordHash }

const HASH_OPTS = { type: argon2.argon2id, memoryCost: 19456, timeCost: 2, parallelism: 1 };

// Verified against when the user doesn't exist, so response time doesn't reveal valid usernames.
const DUMMY_HASH = await argon2.hash("dummy-password", HASH_OPTS);

// ---------- Failed-attempt rate limiter ----------
const LIMITS = {
  perIpAndUser: { max: 5,  windowMs: 15 * 60_000 },  // guessing one account from one IP
  perIp:        { max: 20, windowMs: 15 * 60_000 },  // spraying many accounts from one IP
};
const failures = new Map(); // key -> { count, resetAt }

function retryAfterSeconds(key, { max }) {
  const rec = failures.get(key);
  if (!rec || rec.resetAt <= Date.now()) return 0;
  return rec.count >= max ? Math.ceil((rec.resetAt - Date.now()) / 1000) : 0;
}

function recordFailure(key, { windowMs }) {
  const now = Date.now();
  const rec = failures.get(key);
  if (!rec || rec.resetAt <= now) failures.set(key, { count: 1, resetAt: now + windowMs });
  else rec.count++;
}

// Purge expired entries so the map can't grow without bound.
setInterval(() => {
  const now = Date.now();
  for (const [k, v] of failures) if (v.resetAt <= now) failures.delete(k);
}, 60_000).unref();

// ---------- Helpers ----------
const validCreds = (u, p) =>
  typeof u === "string" && typeof p === "string" &&
  u.length >= 3 && u.length <= 64 && p.length >= 8 && p.length <= 128;

const requireAuth = (req, res, next) =>
  req.session.userId ? next() : res.status(401).json({ error: "Not authenticated" });

// ---------- Routes ----------
app.post("/register", async (req, res) => {
  const { username, password } = req.body ?? {};
  if (!validCreds(username, password)) {
    return res.status(400).json({ error: "Username 3-64 chars, password 8-128 chars" });
  }
  const name = username.toLowerCase();
  if (users.has(name)) return res.status(409).json({ error: "Username taken" });

  const passwordHash = await argon2.hash(password, HASH_OPTS); // salt is generated and embedded
  users.set(name, { id: crypto.randomUUID(), username: name, passwordHash });
  res.status(201).json({ ok: true });
});

app.post("/login", async (req, res) => {
  const { username, password } = req.body ?? {};
  if (typeof username !== "string" || typeof password !== "string" || password.length > 128) {
    return res.status(400).json({ error: "Invalid request" });
  }
  const name = username.toLowerCase();
  const ipUserKey = `${req.ip}|${name}`;
  const ipKey = req.ip;

  // 1. Reject if locked out (checked before doing any hashing work).
  const wait = Math.max(
    retryAfterSeconds(ipUserKey, LIMITS.perIpAndUser),
    retryAfterSeconds(ipKey, LIMITS.perIp)
  );
  if (wait > 0) {
    res.set("Retry-After", String(wait));
    return res.status(429).json({ error: "Too many failed attempts. Try again later." });
  }

  // 2. Verify password (always run a hash verification).
  const user = users.get(name);
  let ok = false;
  try {
    ok = await argon2.verify(user ? user.passwordHash : DUMMY_HASH, password);
  } catch { /* malformed hash: treat as failure */ }
  ok = ok && !!user;

  // 3. Failure: record and return a generic error.
  if (!ok) {
    recordFailure(ipUserKey, LIMITS.perIpAndUser);
    recordFailure(ipKey, LIMITS.perIp);
    return res.status(401).json({ error: "Invalid username or password" });
  }

  // 4. Success: clear the per-user counter, rotate the session ID (prevents fixation).
  failures.delete(ipUserKey);
  req.session.regenerate((err) => {
    if (err) return res.status(500).json({ error: "Session error" });
    req.session.userId = user.id;
    req.session.save((err2) => {
      if (err2) return res.status(500).json({ error: "Session error" });
      res.json({ ok: true });
    });
  });
});

app.post("/logout", (req, res) => {
  req.session.destroy(() => {
    res.clearCookie("sid");
    res.json({ ok: true });
  });
});

app.get("/me", requireAuth, (req, res) => res.json({ userId: req.session.userId }));

app.listen(3000, () => console.log("Listening on :3000"));
