Here's a single-file implementation. It uses `argon2` for hashing, `express-session` for sessions, and a small custom limiter for failed attempts. The user store and limiter are in memory so the example runs on its own.

```bash
npm i express express-session argon2
```

```js
// server.js
const express = require("express");
const session = require("express-session");
const argon2 = require("argon2");

const app = express();
app.use(express.json());
app.set("trust proxy", 1); // only if behind a reverse proxy; makes req.ip correct

// ---------- Sessions ----------
app.use(
  session({
    name: "sid",
    secret: process.env.SESSION_SECRET, // long random string, required
    resave: false,
    saveUninitialized: false,
    // store: new RedisStore({ client })  // MemoryStore leaks and isn't for production
    cookie: {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production", // HTTPS only in prod
      sameSite: "lax",
      maxAge: 1000 * 60 * 60 * 2, // 2 hours
    },
  })
);

// ---------- User store (replace with a DB) ----------
const users = new Map(); // username -> { id, username, passwordHash }

// Hash used to burn equal time when the username doesn't exist,
// so response timing doesn't reveal which usernames are registered.
let DUMMY_HASH;
argon2.hash("dummy-password").then((h) => (DUMMY_HASH = h));

// ---------- Failed-attempt rate limiter ----------
const MAX_FAILS = 5;
const WINDOW_MS = 15 * 60 * 1000; // count failures within 15 min
const LOCK_MS = 15 * 60 * 1000;   // lock duration once exceeded

const attempts = new Map(); // key -> { fails, firstFail, lockedUntil }

// Track per (ip + username) and per ip, so an attacker can't spray many
// usernames from one IP, and can't lock out a victim from everywhere.
const keysFor = (req, username) => [
  `u:${req.ip}:${String(username).toLowerCase()}`,
  `ip:${req.ip}`,
];

function lockedFor(keys) {
  const now = Date.now();
  let wait = 0;
  for (const k of keys) {
    const rec = attempts.get(k);
    if (rec?.lockedUntil > now) wait = Math.max(wait, rec.lockedUntil - now);
  }
  return wait; // ms remaining, 0 if not locked
}

function recordFailure(keys) {
  const now = Date.now();
  keys.forEach((k, i) => {
    // per-IP key gets a higher ceiling since many users may share an IP
    const limit = i === 0 ? MAX_FAILS : MAX_FAILS * 4;
    let rec = attempts.get(k);
    if (!rec || now - rec.firstFail > WINDOW_MS) {
      rec = { fails: 0, firstFail: now, lockedUntil: 0 };
    }
    rec.fails++;
    if (rec.fails >= limit) rec.lockedUntil = now + LOCK_MS;
    attempts.set(k, rec);
  });
}

const clearFailures = (keys) => attempts.delete(keys[0]);

// Periodic cleanup so the map doesn't grow forever
setInterval(() => {
  const now = Date.now();
  for (const [k, r] of attempts) {
    if (now - r.firstFail > WINDOW_MS && r.lockedUntil < now) attempts.delete(k);
  }
}, 60_000).unref();

// ---------- Routes ----------
app.post("/register", async (req, res) => {
  const { username, password } = req.body ?? {};
  if (typeof username !== "string" || typeof password !== "string")
    return res.status(400).json({ error: "Invalid input" });
  if (password.length < 12 || password.length > 128)
    return res.status(400).json({ error: "Password must be 12-128 characters" });
  const key = username.toLowerCase();
  if (users.has(key)) return res.status(409).json({ error: "Username taken" });

  const passwordHash = await argon2.hash(password, { type: argon2.argon2id });
  users.set(key, { id: users.size + 1, username: key, passwordHash });
  res.status(201).json({ ok: true });
});

app.post("/login", async (req, res, next) => {
  try {
    const { username, password } = req.body ?? {};
    if (typeof username !== "string" || typeof password !== "string")
      return res.status(400).json({ error: "Invalid input" });

    const keys = keysFor(req, username);

    const wait = lockedFor(keys);
    if (wait > 0) {
      res.set("Retry-After", Math.ceil(wait / 1000));
      return res.status(429).json({ error: "Too many failed attempts. Try again later." });
    }

    const user = users.get(username.toLowerCase());
    const ok = await argon2.verify(user ? user.passwordHash : DUMMY_HASH, password);

    if (!user || !ok) {
      recordFailure(keys);
      // Same message for unknown user and wrong password
      return res.status(401).json({ error: "Invalid username or password" });
    }

    clearFailures(keys);

    // Regenerate the session ID on login to prevent session fixation
    req.session.regenerate((err) => {
      if (err) return next(err);
      req.session.userId = user.id;
      req.session.username = user.username;
      req.session.save((err) => (err ? next(err) : res.json({ ok: true })));
    });
  } catch (e) {
    next(e);
  }
});

app.post("/logout", (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie("sid");
    res.json({ ok: true });
  });
});

// ---------- Auth middleware + protected route ----------
const requireAuth = (req, res, next) =>
  req.session.userId ? next() : res.status(401).json({ error: "Not authenticated" });

app.get("/me", requireAuth, (req, res) =>
  res.json({ id: req.session.userId, username: req.session.username })
);

app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: "Server error" });
});

app.listen(3000, () => console.log("http://localhost:3000"));
```

