  const now = Date.now();
  let e = attempts.get(key);
  if (!e || (now - e.first > WINDOW_MS && now > e.lockedUntil)) {
    e = { fails: 0, first: now, lockedUntil: 0 };
    attempts.set(key, e);
  }
  return e;
}

function retryAfter(key) {
  const e = attempts.get(key);
  if (!e) return 0;
