Here's a complete, self-contained implementation. It uses `argon2` for hashing, `express-session` for sessions, and a per-account and per-IP limiter for failed attempts.

## Install

```bash
npm i express express-session argon2 better-sqlite3
```

## `server.js`

```js
const express = require("express");
const session = require("express-session");
const argon2 = require("argon2");
const Database = require("better-sqlite3");
const crypto = require("crypto");

const app = express();
app.use(express.json());

// ---------- DB ----------
const db = new Database("app.db");
db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY,
    email TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL
  );
  CREATE TABLE IF NOT EXISTS login_failures (
    key TEXT PRIMARY KEY,          -- "acct:<email>" or "ip:<addr>"
    count INTEGER NOT NULL,
    window_start INTEGER NOT NULL,
    locked_until INTEGER NOT NULL DEFAULT 0
  );
`);

// ---------- Sessions ----------
if (!process.env.SESSION_SECRET) throw new Error("SESSION_SECRET is required");
app.set("trust proxy", 1); // only if behind exactly one reverse proxy
app.use(
  session({
    name: "sid",
    secret: process.env.SESSION_SECRET,
    resave: false,
    saveUninitialized: false,
    // NOTE: default MemoryStore is for dev only. Use connect-redis or
    // better-sqlite3-session-store in production.
    cookie: {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      maxAge: 1000 * 60 * 60 * 8, // 8h
    },
  })
);

// ---------- Rate limiting of failed attempts ----------
const LIMITS = {
  acct: { max: 5, windowMs: 15 * 60_000, lockMs: 15 * 60_000 },
  ip: { max: 20, windowMs: 15 * 60_000, lockMs: 15 * 60_000 },
};

const getRow = db.prepare("SELECT * FROM login_failures WHERE key = ?");
const putRow = db.prepare(`
  INSERT INTO login_failures (key, count, window_start, locked_until)
  VALUES (@key, @count, @window_start, @locked_until)
  ON CONFLICT(key) DO UPDATE SET
    count = @count, window_start = @window_start, locked_until = @locked_until
`);
const delRow = db.prepare("DELETE FROM login_failures WHERE key = ?");

function lockedFor(key) {
  const row = getRow.get(key);
  const now = Date.now();
  return row && row.locked_until > now ? row.locked_until - now : 0;
}

function recordFailure(key, { max, windowMs, lockMs }) {
  const now = Date.now();
  let row = getRow.get(key);
  if (!row || now - row.window_start > windowMs) {
    row = { key, count: 0, window_start: now, locked_until: 0 };
  }
  row.count += 1;
  if (row.count >= max) row.locked_until = now + lockMs;
  putRow.run(row);
}

// Keyed on the *submitted* email (even if no such user exists), so the
// lockout response doesn't reveal which accounts are real.
const acctKey = (email) => "acct:" + email;
const ipKey = (req) => "ip:" + req.ip;

function loginLimiter(req, res, next) {
  const email = String(req.body?.email || "").trim().toLowerCase();
  const wait = Math.max(lockedFor(ipKey(req)), lockedFor(acctKey(email)));
  if (wait > 0) {
    res.set("Retry-After", String(Math.ceil(wait / 1000)));
    return res.status(429).json({ error: "Too many failed attempts. Try again later." });
  }
  next();
}

// ---------- Helpers ----------
const ARGON_OPTS = { type: argon2.argon2id, memoryCost: 19456, timeCost: 2, parallelism: 1 };

// Precomputed hash so unknown-email logins take the same time as real ones.
const DUMMY_HASH_PROMISE = argon2.hash(crypto.randomBytes(16).toString("hex"), ARGON_OPTS);

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: "Not authenticated" });
  next();
}

// ---------- Routes ----------
app.post("/register", async (req, res) => {
  const email = String(req.body?.email || "").trim().toLowerCase();
  const password = String(req.body?.password || "");
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email))
    return res.status(400).json({ error: "Invalid email" });
  if (password.length < 10 || password.length > 128)
    return res.status(400).json({ error: "Password must be 10–128 characters" });

  const hash = await argon2.hash(password, ARGON_OPTS);
  try {
    db.prepare("INSERT INTO users (email, password_hash) VALUES (?, ?)").run(email, hash);
  } catch (e) {
    if (e.code === "SQLITE_CONSTRAINT_UNIQUE")
      return res.status(409).json({ error: "Email already registered" });
    throw e;
  }
  res.status(201).json({ ok: true });
});

app.post("/login", loginLimiter, async (req, res, next) => {
  try {
    const email = String(req.body?.email || "").trim().toLowerCase();
    const password = String(req.body?.password || "");
    if (password.length > 128) return res.status(400).json({ error: "Invalid credentials" });

    const user = db.prepare("SELECT * FROM users WHERE email = ?").get(email);
    const hash = user ? user.password_hash : await DUMMY_HASH_PROMISE;
    const ok = await argon2.verify(hash, password);

    if (!user || !ok) {
      recordFailure(ipKey(req), LIMITS.ip);
      recordFailure(acctKey(email), LIMITS.acct);
      return res.status(401).json({ error: "Invalid email or password" });
    }

    // Success: clear this account's counter (keep the IP counter so one IP
    // can't reset its budget by logging into its own account).
    delRow.run(acctKey(email));

    // Rehash if parameters have been strengthened since this hash was made.
    if (argon2.needsRehash(user.password_hash, ARGON_OPTS)) {
      const newHash = await argon2.hash(password, ARGON_OPTS);
      db.prepare("UPDATE users SET password_hash = ? WHERE id = ?").run(newHash, user.id);
    }

    // Regenerate the session ID to prevent session fixation.
    req.session.regenerate((err) => {
      if (err) return next(err);
      req.session.userId = user.id;
      req.session.save((err2) => (err2 ? next(err2) : res.json({ ok: true })));
    });
  } catch (e) {
    next(e);
  }
});

app.post("/logout", (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie("sid");
    res.json({ ok: true });
  });
});

app.get("/me", requireAuth, (req, res) => {
  const u = db.prepare("SELECT id, email FROM users WHERE id = ?").get(req.session.userId);
  res.json(u);
});

app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: "Internal error" });
});

app.listen(3000, () => console.log("http://localhost:3000"));
