const express = require("express");
const session = require("express-session");
const helmet = require("helmet");
const argon2 = require("argon2");

const app = express();
app.use(helmet());
app.use(express.json({ limit: "10kb" }));

// ---------- Sessions ----------
if (!process.env.SESSION_SECRET) throw new Error("SESSION_SECRET is required");

app.set("trust proxy", 1); // only if behind exactly one reverse proxy; needed for correct req.ip

app.use(
  session({
    name: "sid",
    secret: process.env.SESSION_SECRET,
    resave: false,
    saveUninitialized: false, // no session until login
    // NOTE: default MemoryStore is dev-only. Use connect-redis or similar in production.
    cookie: {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      maxAge: 1000 * 60 * 60 * 2, // 2 hours
    },
  })
);

// ---------- Fake user store (replace with a DB) ----------
const users = new Map(); // username -> { id, passwordHash }
let nextId = 1;

// Hash used to burn equal time when the user doesn't exist (prevents user enumeration by timing)
let DUMMY_HASH;
argon2.hash("dummy-password").then((h) => (DUMMY_HASH = h));

const HASH_OPTS = { type: argon2.argon2id, memoryCost: 19456, timeCost: 2, parallelism: 1 };

// ---------- Failed-login rate limiter ----------
const MAX_FAILS = 5;
const WINDOW_MS = 15 * 60 * 1000;
const MAX_FAILS_PER_IP = 20; // broader cap against one IP spraying many usernames

const failures = new Map(); // key -> { count, resetAt }

function getEntry(key) {
  const e = failures.get(key);
  if (e && e.resetAt <= Date.now()) {
    failures.delete(key);
    return undefined;
  }
  return e;
}

function retryAfterSeconds(key, max) {
  const e = getEntry(key);
  return e && e.count >= max ? Math.ceil((e.resetAt - Date.now()) / 1000) : 0;
}

function recordFailure(key) {
  const e = getEntry(key);
  if (e) e.count++;
  else failures.set(key, { count: 1, resetAt: Date.now() + WINDOW_MS });
}

// Periodic cleanup so the map can't grow forever
setInterval(() => {
  const now = Date.now();
  for (const [k, v] of failures) if (v.resetAt <= now) failures.delete(k);
}, 60 * 1000).unref();

// ---------- Helpers ----------
const isStr = (v, max) => typeof v === "string" && v.length > 0 && v.length <= max;

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: "Not authenticated" });
  next();
}

// ---------- Routes ----------
app.post("/register", async (req, res) => {
  const { username, password } = req.body ?? {};
  if (!isStr(username, 64) || !isStr(password, 128) || password.length < 10) {
    return res.status(400).json({ error: "Invalid username or password (min 10 chars)" });
  }
  const name = username.toLowerCase();
  if (users.has(name)) return res.status(409).json({ error: "Username taken" });

  users.set(name, { id: nextId++, passwordHash: await argon2.hash(password, HASH_OPTS) });
  res.status(201).json({ ok: true });
});

app.post("/login", async (req, res, next) => {
  try {
    const { username, password } = req.body ?? {};
    if (!isStr(username, 64) || !isStr(password, 128)) {
      return res.status(400).json({ error: "Invalid credentials" });
    }

    const name = username.toLowerCase();
    const ipKey = `ip:${req.ip}`;
    const accountKey = `acct:${name}:${req.ip}`; // per-account+IP: stops brute force without letting attackers lock out the real user from elsewhere

    // Check lockout BEFORE doing any password work
    const wait = Math.max(
      retryAfterSeconds(accountKey, MAX_FAILS),
      retryAfterSeconds(ipKey, MAX_FAILS_PER_IP)
    );
    if (wait > 0) {
      res.set("Retry-After", String(wait));
      return res.status(429).json({ error: "Too many failed attempts. Try again later." });
    }

    const user = users.get(name);
    // Always run a verify so timing doesn't reveal whether the user exists
    const ok = await argon2.verify(user ? user.passwordHash : DUMMY_HASH, password);

    if (!user || !ok) {
      recordFailure(accountKey);
      recordFailure(ipKey);
      return res.status(401).json({ error: "Invalid username or password" });
    }

    failures.delete(accountKey); // success resets the per-account counter

    // Regenerate the session ID to prevent session fixation
    req.session.regenerate((err) => {
      if (err) return next(err);
      req.session.userId = user.id;
      req.session.username = name;
      req.session.save((err) => (err ? next(err) : res.json({ ok: true })));
    });
  } catch (err) {
    next(err);
  }
});

app.post("/logout", (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie("sid");
    res.json({ ok: true });
  });
});

app.get("/me", requireAuth, (req, res) => {
  res.json({ id: req.session.userId, username: req.session.username });
});

// ---------- Error handler ----------
app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: "Internal server error" });
});

app.listen(3000, () => console.log("Listening on :3000"));
