const express = require("express");
const session = require("express-session");
const argon2 = require("argon2");
const crypto = require("crypto");

const app = express();
app.use(express.json());

app.set("trust proxy", 1); // only if behind a reverse proxy

app.use(
  session({
    name: "sid",
    secret: process.env.SESSION_SECRET, // long random string, required
    resave: false,
    saveUninitialized: false,
    // Use a persistent store (connect-redis etc.) in production; MemoryStore leaks
    cookie: {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      maxAge: 1000 * 60 * 60 * 2, // 2 hours
    },
  })
);

// ---------- "database" (replace with a real one) ----------
const users = new Map(); // email -> { id, email, passwordHash }

// ---------- failed-attempt rate limiter ----------
const MAX_FAILS = 5;
const WINDOW_MS = 15 * 60 * 1000;
const LOCK_MS = 15 * 60 * 1000;
const attempts = new Map(); // key -> { count, first, lockedUntil }

function check(key) {
  const rec = attempts.get(key);
  if (!rec) return 0;
  const now = Date.now();
  if (rec.lockedUntil > now) return rec.lockedUntil - now;
  if (now - rec.first > WINDOW_MS) attempts.delete(key);
  return 0;
}

function recordFail(key) {
  const now = Date.now();
  let rec = attempts.get(key);
  if (!rec || now - rec.first > WINDOW_MS) {
    rec = { count: 0, first: now, lockedUntil: 0 };
    attempts.set(key, rec);
  }
  rec.count++;
  if (rec.count >= MAX_FAILS) rec.lockedUntil = now + LOCK_MS;
}

// Periodic cleanup so the map doesn't grow forever
setInterval(() => {
  const now = Date.now();
  for (const [k, r] of attempts)
    if (r.lockedUntil < now && now - r.first > WINDOW_MS) attempts.delete(k);
}, 60 * 1000).unref();

// ---------- helpers ----------
const ARGON_OPTS = { type: argon2.argon2id, memoryCost: 19456, timeCost: 2, parallelism: 1 };
// Dummy hash so unknown users take the same time as known ones (prevents user enumeration)
let DUMMY_HASH;
argon2.hash("dummy-password", ARGON_OPTS).then((h) => (DUMMY_HASH = h));

const normEmail = (e) => String(e || "").trim().toLowerCase();

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: "Not authenticated" });
  next();
}

// ---------- routes ----------
app.post("/register", async (req, res) => {
  const email = normEmail(req.body.email);
  const password = req.body.password;
  if (!/^\S+@\S+\.\S+$/.test(email) || typeof password !== "string" || password.length < 10 || password.length > 128)
    return res.status(400).json({ error: "Invalid email or password (10-128 chars)" });
  if (users.has(email)) return res.status(409).json({ error: "Unable to register" });

  const passwordHash = await argon2.hash(password, ARGON_OPTS);
  users.set(email, { id: crypto.randomUUID(), email, passwordHash });
  res.status(201).json({ ok: true });
});

app.post("/login", async (req, res) => {
  const email = normEmail(req.body.email);
  const password = req.body.password;
  if (!email || typeof password !== "string" || password.length > 128)
    return res.status(400).json({ error: "Invalid request" });

  const ipKey = `ip:${req.ip}`;
  const acctKey = `acct:${email}`;

  const wait = Math.max(check(ipKey), check(acctKey));
  if (wait > 0) {
    res.set("Retry-After", String(Math.ceil(wait / 1000)));
    return res.status(429).json({ error: "Too many failed attempts. Try again later." });
  }

  const user = users.get(email);
  const ok = await argon2.verify(user ? user.passwordHash : DUMMY_HASH, password).catch(() => false);

  if (!user || !ok) {
    recordFail(ipKey);
    recordFail(acctKey);
    return res.status(401).json({ error: "Invalid email or password" });
  }

  // Success: clear the account counter (keep the IP counter so one IP can't reset it by logging into its own account)
  attempts.delete(acctKey);

  // Regenerate session to prevent session fixation
  req.session.regenerate((err) => {
    if (err) return res.status(500).json({ error: "Login failed" });
    req.session.userId = user.id;
    req.session.save(() => res.json({ ok: true }));
  });
});

app.post("/logout", (req, res) => {
  req.session.destroy(() => {
    res.clearCookie("sid");
    res.json({ ok: true });
  });
});

app.get("/me", requireAuth, (req, res) => res.json({ userId: req.session.userId }));

app.listen(3000, () => console.log("http://localhost:3000"));
