**How it works**

- **Password hashing:** Argon2id with the OWASP-recommended minimum parameters. Salts are generated automatically and stored inside the hash string.
- **Timing and enumeration:** Unknown emails are verified against a dummy hash. The error message is identical for a wrong password and an unknown user.
- **Sessions:**
  - The session ID is regenerated on login to prevent fixation.
  - The cookie is `httpOnly`, `sameSite=lax`, and `secure` in production.
  - `saveUninitialized: false` means no session is created until login.
- **Rate limiting:** Failed attempts are counted per IP and per account. After 5 failures in 15 minutes, both return `429` with a `Retry-After` header for 15 minutes. Checking the lockout before the password verification also avoids the expensive hash work while locked out.

**Before going to production**

1. **Persistent stores:** Swap `MemoryStore` for Redis (`connect-redis`), and move the `attempts` map to Redis too. Otherwise limits reset on restart and don't work across multiple instances.
2. **Account-lockout DoS:** Per-account lockout lets an attacker lock out a victim by deliberately failing logins. Options include tracking the `(ip, account)` pair instead, adding a CAPTCHA, or using progressive delays instead of hard locks.
3. **CSRF:** `sameSite=lax` covers a lot, but add a CSRF token (or require a custom header) for state-changing routes if you serve browser forms.
4. **HTTPS and headers:** Serve over HTTPS only and add `helmet`. Also add a general rate limiter (e.g. `express-rate-limit`) on `/register` and other routes.
5. **Passwords:** Consider checking passwords against a breach list, and invalidate a user's other sessions after a password change.

```js
// server.js  —  npm i express express-session express-rate-limit
import crypto from 'node:crypto';
import { promisify } from 'node:util';
import express from 'express';
import session from 'express-session';
import { rateLimit, ipKeyGenerator } from 'express-rate-limit';

const scrypt = promisify(crypto.scrypt);

// --- password hashing (stdlib scrypt, per-user salt) ---
async function hash(pw) {
  const salt = crypto.randomBytes(16);
  return `${salt.toString('hex')}:${(await scrypt(pw, salt, 64)).toString('hex')}`;
}
async function verify(pw, stored) {
  const [salt, key] = stored.split(':');
  const got = await scrypt(pw, Buffer.from(salt, 'hex'), 64);
  return crypto.timingSafeEqual(got, Buffer.from(key, 'hex'));
}

// ponytail: in-memory users, swap for a DB table (username unique, hash column)
const users = new Map();
const DUMMY = await hash('dummy'); // compared when user is unknown, so timing doesn't reveal usernames

const app = express();
app.use(express.json());
app.use(session({
  secret: process.env.SESSION_SECRET, // required, long random string
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, sameSite: 'lax', secure: process.env.NODE_ENV === 'production', maxAge: 864e5 },
  // ponytail: MemoryStore leaks and doesn't scale; use connect-redis or similar in prod
}));

// counts only FAILED logins (2xx responses are skipped): 5 per 15 min per IP+username
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 5,
  skipSuccessfulRequests: true,
  keyGenerator: (req) => `${ipKeyGenerator(req.ip)}|${String(req.body?.username).toLowerCase()}`,
  message: { error: 'Too many failed attempts, try later' },
});

app.post('/register', async (req, res) => {
  const { username, password } = req.body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string' || !username || password.length < 8)
    return res.status(400).json({ error: 'username and password (8+ chars) required' });
  const key = username.toLowerCase();
  if (users.has(key)) return res.status(409).json({ error: 'taken' });
  users.set(key, await hash(password));
  res.sendStatus(201);
});

app.post('/login', loginLimiter, async (req, res) => {
  const { username, password } = req.body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string')
    return res.status(400).json({ error: 'bad request' });
  const key = username.toLowerCase();
  const stored = users.get(key);
  const ok = await verify(password, stored ?? DUMMY);
  if (!stored || !ok) return res.status(401).json({ error: 'invalid credentials' });
  req.session.regenerate((err) => { // new session id on login: prevents fixation
    if (err) return res.sendStatus(500);
    req.session.user = key;
    res.json({ ok: true });
  });
});

app.post('/logout', (req, res) => req.session.destroy(() => res.clearCookie('connect.sid').sendStatus(204)));

const requireAuth = (req, res, next) => (req.session.user ? next() : res.sendStatus(401));
app.get('/me', requireAuth, (req, res) => res.json({ user: req.session.user }));

app.listen(3000);
