const users = new Map();

// scrypt (stdlib), per-user random salt, constant-time compare
async function hash(pw) {
  const salt = crypto.randomBytes(16);
  return `${salt.toString('hex')}:${(await scrypt(pw, salt, 64)).toString('hex')}`;
}
async function verify(pw, stored) {
  const [salt, key] = stored.split(':').map(h => Buffer.from(h, 'hex'));
  return crypto.timingSafeEqual(await scrypt(pw, salt, 64), key);
