// ponytail: in-memory, never pruned except on retry, so use Redis with TTL for multi-process or long uptime.
// Keying on ip+username means rotating IPs bypasses it; a per-username key fixes that but lets attackers lock victims out.
const MAX = 5, WINDOW = 15 * 60e3;
const fails = new Map();
const lockedFor = key => {
  const f = fails.get(key);
  if (!f) return 0;
  if (Date.now() > f.reset) { fails.delete(key); return 0; }
  return f.n >= MAX ? f.reset - Date.now() : 0;
};
const recordFail = key => {
  const f = fails.get(key);
  if (!f || Date.now() > f.reset) fails.set(key, { n: 1, reset: Date.now() + WINDOW });
  else f.n++;
};

const valid = (u, p) => typeof u === 'string' && typeof p === 'string' && u && u.length <= 64 && p.length >= 8 && p.length <= 128;

app.post('/register', async (req, res) => {
