  return `${salt.toString('hex')}:${hash.toString('hex')}`;
}
async function verifyPassword(password, stored) {
  const [salt, hash] = stored.split(':').map((h) => Buffer.from(h, 'hex'));
  const candidate = await scrypt(password, salt, 64);
  return crypto.timingSafeEqual(candidate, hash);
}

// token-miser: in-memory user store; replace with a database
const users = new Map();
let dummyHash; // verified against for unknown users so timing doesn't reveal which usernames exist
hashPassword('dummy').then((h) => (dummyHash = h));

app.post('/register', async (req, res) => {
  const { username, password } = req.body;
  if (typeof username !== 'string' || typeof password !== 'string' ||
      !username || password.length < 8 || password.length > 128) {
    return res.status(400).json({ error: 'Invalid username or password (min 8 chars)' });
  }
  if (users.has(username)) return res.status(409).json({ error: 'Username taken' });
  users.set(username, { id: crypto.randomUUID(), passwordHash: await hashPassword(password) });
  res.sendStatus(201);
});

// Failed-attempt limiter, keyed by ip + username: 5 failures per 15 min locks that key
const MAX_FAILS = 5;
const WINDOW_MS = 15 * 60 * 1000;
const fails = new Map(); // key -> { count, resetAt }
// token-miser: per-process map; use Redis for multiple instances. Also consider a per-IP cap to stop one IP spraying many usernames.
setInterval(() => {
  const now = Date.now();
  for (const [k, v] of fails) if (v.resetAt <= now) fails.delete(k);
}, 60 * 1000).unref();

function loginLimiter(req, res, next) {
  const username = typeof req.body.username === 'string' ? req.body.username.toLowerCase() : '';
  req.limitKey = `${req.ip}|${username}`;
  const entry = fails.get(req.limitKey);
  if (entry && entry.resetAt > Date.now() && entry.count >= MAX_FAILS) {
    res.set('Retry-After', Math.ceil((entry.resetAt - Date.now()) / 1000));
    return res.status(429).json({ error: 'Too many failed attempts. Try again later.' });
  }
  next();
}

app.post('/login', loginLimiter, async (req, res) => {
  const { username, password } = req.body;
  if (typeof username !== 'string' || typeof password !== 'string' || password.length > 128) {
    return res.status(400).json({ error: 'Invalid request' });
  }
  const user = users.get(username);
  const ok = await verifyPassword(password, user ? user.passwordHash : dummyHash);

  if (!user || !ok) {
    const now = Date.now();
    const e = fails.get(req.limitKey);
    if (!e || e.resetAt <= now) fails.set(req.limitKey, { count: 1, resetAt: now + WINDOW_MS });
    else e.count++;
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  fails.delete(req.limitKey);
  req.session.regenerate((err) => { // new session ID prevents fixation
    if (err) return res.sendStatus(500);
    req.session.userId = user.id;
    res.json({ ok: true });
  });
});

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.sendStatus(401);
  next();
}

app.post('/logout', (req, res) => {
  req.session.destroy(() => {
    res.clearCookie('sid');
    res.sendStatus(204);
  });
});

app.get('/me', requireAuth, (req, res) => res.json({ userId: req.session.userId }));

app.listen(3000);
```

The code uses `crypto.scrypt` from Node's standard library, so it needs no bcrypt dependency. It compares hashes in constant time and verifies against a dummy hash for unknown users, which keeps response time from revealing whether a username exists. The limiter counts only failed attempts and clears the count on a successful login.

Left out: CSRF tokens (`sameSite: 'strict'` covers most cases), HTTPS setup, and account lockout notifications. Add them if you serve cross-site requests or handle sensitive accounts.

