const express = require('express');
const session = require('express-session');
const bcrypt = require('bcrypt');
const { rateLimit, ipKeyGenerator } = require('express-rate-limit');

const app = express();
app.use(express.json());
app.set('trust proxy', 1); // only if behind exactly one proxy; otherwise remove

app.use(session({
  secret: process.env.SESSION_SECRET, // long random string, required
  name: 'sid',
  resave: false,
  saveUninitialized: false,
  // token-miser: default MemoryStore leaks and loses sessions on restart; use connect-redis or similar in production
  cookie: {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    maxAge: 1000 * 60 * 60 * 8,
  },
}));

// token-miser: in-memory users; replace with a database table (unique username)
const users = new Map();
const DUMMY_HASH = bcrypt.hashSync('dummy-password', 12);

// Counts only failed attempts (status >= 400), per IP + username: 5 per 15 min.
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 5,
  skipSuccessfulRequests: true,
  standardHeaders: 'draft-7',
  legacyHeaders: false,
  keyGenerator: (req) =>
    `${ipKeyGenerator(req.ip)}:${String(req.body?.username ?? '').toLowerCase()}`,
  message: { error: 'Too many failed attempts. Try again later.' },
});

const valid = (u, p) =>
  typeof u === 'string' && typeof p === 'string' &&
  u.length >= 3 && u.length <= 64 && p.length >= 8 && p.length <= 72; // bcrypt ignores bytes past 72

app.post('/register', async (req, res) => {
  const { username, password } = req.body ?? {};
  if (!valid(username, password)) return res.status(400).json({ error: 'Invalid input' });
  const key = username.toLowerCase();
  if (users.has(key)) return res.status(409).json({ error: 'Username taken' });
  users.set(key, { username, hash: await bcrypt.hash(password, 12) });
  res.status(201).json({ ok: true });
});

app.post('/login', loginLimiter, async (req, res, next) => {
  try {
    const { username, password } = req.body ?? {};
    if (!valid(username, password)) return res.status(400).json({ error: 'Invalid input' });

    const user = users.get(username.toLowerCase());
    // Always run bcrypt so response time doesn't reveal whether the user exists.
    const ok = await bcrypt.compare(password, user ? user.hash : DUMMY_HASH);
    if (!user || !ok) return res.status(401).json({ error: 'Invalid credentials' });

